const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Jabal Qidr is a dark volcanic cone in the Harrat Khaybar volcanic field.
    const jabalQidr = ee.geometry.Point([37.352, 26.601]).buffer(500);
    // Jabal Bayda is a nearby "white mountain" made of light-colored comendite lava.
    const jabalBayda = ee.geometry.Point([39.921, 25.723]).buffer(500);

    const startDate = '2024-04-01';
    const endDate = '2024-04-30';

    // 2. Data Acquisition & Pre-processing
    // Function to mask clouds using the QA60 band for Sentinel-2 L2A.
    function maskS2clouds(image) {
        const qa = image.select('QA60');
        // Bits 10 and 11 are clouds and cirrus, respectively.
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        // Both flags should be set to zero, indicating clear conditions.
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
            .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000); // Scale to reflectance
    }

    // Attempt to get Sentinel-2 data
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(startDate, endDate)
        .filter(ee.Filter.or(ee.Filter.bounds(jabalQidr), ee.Filter.bounds(jabalBayda)))
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

    // 3. Data Availability Check (C1)
    const imageCount = collection.size().getInfo();
    if (imageCount === 0) {
        console.log("Evidence: No suitable Sentinel-2 images found for April 2024.");
        console.log("A: No");
        return;
    }

    // Create a cloud-free mosaic
    const mosaic = collection.map(maskS2clouds).median();

    // 4. Processing & Calculation
    // Brightness will be the mean of the visible bands (Blue, Green, Red).
    const bands = ['B2', 'B3', 'B4'];

    const qidrMean = mosaic.select(bands).reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: jabalQidr,
        scale: 30,
        maxPixels: 1e9
    });

    const baydaMean = mosaic.select(bands).reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: jabalBayda,
        scale: 30,
        maxPixels: 1e9
    });

    const qidrBrightness = ee.Number(qidrMean.get('B2')).add(qidrMean.get('B3')).add(qidrMean.get('B4')).divide(3);
    const baydaBrightness = ee.Number(baydaMean.get('B2')).add(baydaMean.get('B3')).add(baydaMean.get('B4')).divide(3);

    // Get pixel counts for validation (C2)
    const qidrCount = mosaic.select('B2').reduceRegion({reducer: ee.Reducer.count(), geometry: jabalQidr, scale: 30, maxPixels: 1e9}).get('B2').getInfo();
    const baydaCount = mosaic.select('B2').reduceRegion({reducer: ee.Reducer.count(), geometry: jabalBayda, scale: 30, maxPixels: 1e9}).get('B2').getInfo();

    if (qidrCount === 0 || baydaCount === 0) {
        console.log(`Evidence: After cloud masking, no valid pixels remained.`);
        console.log(`Jabal Qidr Pixels: ${qidrCount}`);
        console.log(`Jabal Bayda Pixels: ${baydaCount}`);
        console.log("B: No");
        return;
    }

    const qidrResult = qidrBrightness.getInfo();
    const baydaResult = baydaBrightness.getInfo();

    // 5. Validation & Final Answer (C3)
    if (qidrResult === null || baydaResult === null || isNaN(qidrResult) || isNaN(baydaResult)) {
        console.log("Evidence: Calculation failed. Result was null or NaN.");
        console.log(`Jabal Qidr Brightness: ${qidrResult}`);
        console.log(`Jabal Bayda Brightness: ${baydaResult}`);
        console.log("C3: Calculation Failure");
        return;
    }

    const isDarker = qidrResult < baydaResult;

    console.log(`Evidence: Analysis of Sentinel-2 imagery for April 2024.`);
    console.log(`Image count: ${imageCount}`);
    console.log(`Jabal Qidr average visible reflectance: ${qidrResult.toFixed(4)}`);
    console.log(`Jabal Bayda average visible reflectance: ${baydaResult.toFixed(4)}`);
    console.log(`Jabal Qidr is darker than Jabal Bayda: ${isDarker}`);

    if (isDarker) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during Earth Engine initialization or analysis.");
        console.error(e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
